#!/usr/bin/env python3

filepath = "/Users/Paul.Chernoch/Documents/GitHub/paulchernoch/source/synopsis.yaml"

with open(filepath, "r") as f:
    content = f.read()

synopses = {
    "120-is-for-consecration.md": "The number 120 carries a dual meaning throughout Scripture: consecration for service and divine judgment. From the 120 priests blowing trumpets at Solomon's temple dedication to the 120 believers present at Pentecost, the number marks people set apart by God. It factors as 10 x 12, combining secular and consecrated completeness, and as 3 x 40, three periods of trial and testing. The article traces 120 from Genesis to Revelation, concluding that consecration and judgment are two sides of the same coin — and that 144,000 = 120 x 120 x 10 seals this meaning in the end-times drama.",
    "153-and-fear.md": "Through calendar arithmetic applied to the dates of Noah's Flood, this article reveals a surprising link between the number 153 and the biblical theme of fearing the Lord. The flood began on the 17th of the 2nd month and ended on the 17th of the 7th month, and (17 x 2) + (17 x 7) = 153, pointing directly to Psalms 34 and 119 — the two chapters in Scripture most focused on the fear of the Lord. Additional reinforcement comes from Luke 12 and 2 Kings 17, both chapters freighted with the word fear. The article concludes that the flood itself was designed to teach mankind to fear God, making 153 a number encoding that reverent awe.",
    "153-and-hope.md": "Starting with Jeremiah's purchase of property for seventeen shekels as Jerusalem fell to Babylon, this article shows how the number seventeen — a factor of 153 — carries a meaning of hope amid catastrophe. A careful count of the word deed in Jeremiah 32 reveals a hidden 9 x 17 = 153 structure, tying the chapter to John 21's miraculous catch. Prophetic timelines then trace multiples of seventeen from Jerusalem's fall in 586 BC to its liberation in 1917 and Israel's rebirth in 1948. Seventeen, and by extension 153, thus means victory over sin and hope for restoration — even when no evidence of that hope can yet be seen.",
    "153-and-the-fifth-trumpet.md": "This article connects the 153-day duration of Noah's Flood to the five months of the fifth trumpet in Revelation 9, interpreting each prophetic day as one year for a total of 153 years. The locusts of Revelation — crowned, with women's hair and iron breastplates — are identified as the Christian queens of European colonial empires during the Industrial Revolution (1765-1918). That 153-year period fulfilled Habakkuk's prophecies against Islamic civilization, culminating in Britain's capture of Jerusalem in 1917 and the dissolution of the Ottoman Empire. The article demonstrates that these locusts distinguished between those sealed by God and all other peoples, exactly as the biblical text demands.",
    "153-connections.md": "This introductory article to a multi-part series reveals the author's discovery of a sweeping connection between the 153 fish in John 21, the prophecies of Habakkuk, and the fifth trumpet of Revelation 9. After correcting an earlier error in calculating the five months of Revelation using queens' reign durations, studying Noah's Flood provided the true solution: 153 days equals five 30-day months. John 21's fishing miracle shares key themes with Habakkuk — nets, fish, nakedness, and sheep — connecting them through a web of shared imagery. The article serves as a map to the multi-part inquiry that will untangle the meaning of 153 across Genesis, Psalms, Jeremiah, Matthew, John, Habakkuk, and Revelation.",
    "153-is-for-total-victory.md": "This overview article introduces a multi-part series exploring the number 153, which the author identifies as a symbol of total victory drawn from the miraculous catch of fish in John 21. The series traces 153 across six key meanings: total victory, the fear of God, hope amid war, judgment for the wicked, forgiveness for the righteous, and power for the righteous. As the seventeenth triangular number (1+2+...+17=153), the number links Habakkuk's seven-section structure to themes of victory, since the 17th verses of all three chapters of Habakkuk address the triumph of good over evil. Readers are directed to individual articles in the series that develop each of these themes in depth.",
    "17-is-for-victory.md": "The number seventeen encodes the biblical theme of divine victory over human opposition, being the sum of seven (divine completeness) and ten (human completeness). The beast of Revelation 13 has seven heads and ten horns — seventeen combined — representing the enemy that God will vanquish, while Paul lists seventeen adversaries in Romans 8 that believers overcome through Christ. The most dramatic example is Noah's Flood, which began and ended on the seventeenth day of different months, marking God's total triumph over human wickedness. By century, by month, and by day, seventeen consistently signals God's victorious hand at work in history.",
    "2-is-for-jesus.md": "The number two in Scripture points to Jesus Christ — the Word of God given in two testaments, a man of two natures (divine and human) who will visit the world twice. Psalm 2 prophesies of Jesus as God's anointed, begotten Son who will rule the nations with a rod of iron, inviting all to kiss the Son lest his wrath be kindled. In the Gospels, two people literally kiss Jesus: Mary of Bethany in loving gratitude and Judas in betrayal, precisely fulfilling the Psalm's dual promise of refuge for the humble and wrath for the treacherous. The number two thus captures the complete arc of Christ's relationship with humanity: an offer of peace now and a judgment to come.",
    "210-is-for-peace.md": "The number 210 is connected to the lifespan of Job, who — adding seventy years before his trials to the 140 years of restored blessing — lived to age 210. The article shows that 210 = 42 x 5, with forty-two representing the struggle leading to victory and five the grace of a harvest, a perfect description of Job's journey from suffering to restoration. Breaking the number down further as 2 x 3 x 5 x 7 connects it to all three persons of the Trinity, each of whom played a distinct role in Job's transformation. When Job died old and full of days, Scripture declared his peace, making 210 the number for a life of hard-won peace.",
    "28-is-for-time.md": "The number twenty-eight structures the Seven Pillars of Wisdom books — Psalms, Job, Proverbs, Song of Songs, and others — by mapping twenty-eight times from Ecclesiastes 3 onto each book's chapters or major sections. The article dismisses common biblical trivia about the number and focuses instead on how the Growth Pattern of twenty-eight phases traces either a spiral upward toward heavenly peace or a downward spiral into ruin. Each pillar book demonstrates this structure differently: Psalms 1-28, Job chapters 15-42, Proverbs chapters 4-31, and Song of Songs' twenty-eight alternating speeches. Twenty-eight thus serves as a divine temporal map of the soul's journey through life's seasons, linked to the lunar cycle and the rhythms of time itself.",
    "3-is-for-the-father.md": "The number three in Scripture most powerfully signifies the triune God, especially God the Father, whose past-present-future existence — who was, and is, and is to come — is expressed as a threefold formula in both Revelation 1 and 4. Of the five numbers of completeness in Scripture (3, 7, 10, 12, 70), three stands for completeness in divine power and holiness. The article connects three to Psalm 3, where David faces a threefold increase of enemies but has a threefold reliance on God, and the word Selah appears three times as an invitation to wait on the Father. Even in creation, dry ground appearing on the third day — earth that remains forever — points to God the Father as our immovable, eternal foundation.",
    "4-is-for-cycles-of-nature.md": "The number four represents the eternal, faithful cycles of nature — the four seasons, the four directions, and the creation of the sun, moon, and stars on the fourth day to mark off days and years. In Ecclesiastes 1, Solomon meditates on four endless cycles that match the four ancient elements: earth, sun (fire), wind (air), and rivers (water). God's promise to Noah after the Flood names four pairs of opposites — seedtime and harvest, cold and heat, summer and winter, day and night — declaring that these faithful cycles will continue as long as the earth endures. Where seven signifies progression toward completion, four signifies faithful repetition — the farmer's friend and the philosopher's restless lament.",
    "40-is-for-suffering.md": "Forty is among the most consistent of biblical numbers, appearing in story after story with the same unambiguous meaning: suffering, trials, and temptation. Moses spent forty years in each of three phases of his life; Noah's Flood lasted forty days; Jesus fasted forty days in the wilderness; David, Solomon, and Josiah each reigned forty years through conflict-laden eras. The number factors as 10 x 4 — fallen human completeness multiplied by nature's endless repetition — showing that trials come not once but in waves. The article also notes that forty centuries from creation reaches approximately 20 BC, forty centuries during which the whole world was tested without a Savior.",
    "42-is-for-the-journey.md": "Forty-two is the number of struggle and the journey back to God, drawn from Israel's forty-two stages of desert wandering, Matthew's forty-two-name genealogy from Abraham to Jesus, and Revelation's symbolic forty-two months of tribulation. Factoring as 6 x 7 — man's rebellion opposed by God's perfection — forty-two measures how long the battle between good and evil will continue before its final resolution. A second meaning emerges from the Hebrew word for God, Eloah, whose letters sum to 42, making forty-two literally the measure of the immeasurable God. From Nimrod's tower to Israel's wandering to Jesus' genealogy, forty-two invariably traces the path through suffering that leads to God's ultimate victory.",
    "5-is-for-grace.md": "Five is the number of grace, most clearly seen in the five Levitical offerings — burnt, grain, purification, guilt, and peace — which correspond to five stages of God's path from suffering to peace. The article connects this to Noah, Ruth, and David, each of whom found favor (grace) in God's eyes at the fifth mention of their name in Scripture. In the five books of the Pentateuch, five comes alive as the shape of God's discipling path: preparation, plowing through suffering, planting the Word, pouring out the Spirit, and finally peace. Even in creation, the fifth day's birds and sea creatures reflect the Holy Spirit battling Leviathan — wherever five appears, God's grace is at work in the midst of conflict.",
    "6-is-for-man.md": "Six is the number of man and trouble, since humanity was created on the sixth day alongside the beasts that represent evil empires in biblical prophecy. The sixth commandment is against murder, the most violent and irreversible breach of God's law; six cities of refuge were established by Moses to protect the accused from mob vengeance pending a fair trial. The Antichrist's number is 666, a complete trinity of evil, showing humanity's rebellion at its most organized and dangerous. Rome, the sixth and longest-lasting of the major world empires in Daniel's sequence, represents human civilization at its most powerful — an empire of iron teeth that devoured and crushed all it encountered.",
    "7-is-for-the-holy-spirit.md": "Seven is one of the most frequent numbers in Scripture, carrying meanings of completeness, holiness, consecration, and the omnipresence of the Holy Spirit through its identification with the seven spirits of God named in Isaiah 11 and Revelation. Zechariah's vision of the seven-lamp menorah — interpreted as the seven eyes of the Lord ranging through the whole earth — is taken up by John, who identifies the Lamb's seven eyes with the seven spirits of God sent into all the earth. These seven spirits (wisdom, understanding, counsel, might, knowledge, fear of the Lord, and the Spirit of the Lord himself) each illuminate one of the Seven Pillars of Wisdom. Even in nature, the gestational periods of many animals — mice, sheep, dogs, and humans — are multiples of seven days, showing that seven is woven into the very fabric of life.",
    "a-divided-world.md": "Using Solomon's clock of twenty-eight times from Ecclesiastes 3, this article argues that the world is currently in a time to love and is transitioning toward a time to hate beginning around 2040 AD — a period that will bring intensifying division, persecution, and conflict for Jews and Christians alike. The article points to alarming statistics: a 360% rise in antisemitic incidents following the October 2023 Hamas attacks and an eightfold increase in attacks on Christian churches between 2018 and 2023. Yet God is not surprised — Matthew 13's parable of the net teaches that this separation of good and evil is an essential feature of the end-times harvest, not a catastrophe but a divine sorting. The article ends with encouragement that God foresaw all of this and provides the help needed to endure it, if we trust His word, His wisdom, and His will.",
    "a-model-for-the-ordination-of-women.md": "This article argues that while the author accepts the constraints of complementarian passages in 1 Timothy and Ephesians, those constraints do not preclude the possibility that God has ordained women for service — if a proper biblical model of such ordination can be found. Accepting that Christ's death did not immediately open pastoral and elder roles to women, the article sets out six things that must be demonstrated in Scripture: a sacrifice, a ceremony, a prophetic metaphor proving the ceremony applies to women, a prophetic timeframe, a reinterpretation of the restrictive texts, and an explanation for the long delay. The rest of the series examines Job's ordination, the metaphor of childbirth, and Paul's letters to supply those answers. The article functions as a compass pointing toward the following articles in the series.",
    "about.md": "This page introduces the website and its purpose, explaining that it presents organized, carefully considered insights on the Christian faith — not a blog of random thoughts. The site covers two major themes: advice for personal spiritual growth (drawing from the author's own healing from depression, anxiety, and fear) and a novel system of eschatology that sees the structure of individual human life as a mirror of all human history. Navigation features include a table of contents, full-text search, a Scripture index, and section links connecting related articles. The author's doctrinal statement reflects Reformed Baptist convictions, belief in the gifts of the Spirit, Young Earth Creationism, and a recently adopted egalitarian position on women's ordination.",
    "acrostic-clock.md": "Psalms 111 and 112 form an Acrostic Clock — an interlocking pair of Hebrew acrostics where each poetic line begins with a successive letter of the alphabet, mapping forty-four poetic lines to forty-four eras of history. Psalm 111 speaks of the Lord while Psalm 112 mirrors him in the life of the upright person, with the fear of the Lord as the hinge between them. The pair carries the fingerprints of all seven spirits of God and connects to Psalm 119's prophetic clock through its acrostic structure. Examining the era from 642 to 684 AD in this clock's light illuminates Islam's assault on the Trinity, the capture of Jerusalem, and the beginning of the Dark Ages through the psalm's imagery of light dawning in darkness.",
    "against-complementarianism.md": "This article recounts the author's dramatic reversal from a lifelong complementarian position to an egalitarian one, offering a declaration-against-interest — the testimony of someone who stood to lose friends and reputation by changing — as proof that the change was genuine. Three errors in Kathy Keller's complementarian booklet are identified: an overly simplistic appeal to scriptural perspicacity, an admission of ignorance about God's purpose for women's suffering, and an implicit assumption that God has not revealed his plan for women's liberation. The article argues that God has indeed revealed this plan — hidden in biblical patterns that require diligent search — and that the church has been spiritually deaf to it. It promises to show a biblical model of ordination that satisfies even the constraints Keller herself would accept.",
    "alexander-the-great.md": "Using the speech of Zophar in Job 20, this forensic investigation proposes that Alexander the Great's mysterious death is described in prophetic detail in the Bible, centuries before it occurred. Verse by verse, Zophar's description of the fate of the wicked maps onto the documented symptoms of Alexander's illness: the banquet where it began, excruciating abdominal pain, fever, jaundice, delirium, convulsions, and creeping paralysis leading to death within two weeks. The article identifies Zophar with Satan and explains that just as Revelation 13 shows Satan controlling the world's evil empires, Job 20 is the devil's own funeral oration for his fallen servant Alexander. The solution to one of history's great medical mysteries is thus found not in a modern journal but in the oldest book of the Bible.",
    "author.md": "Paul Anton Chernoch introduces himself as a physics graduate of MIT, a software engineer, and a theologian who has spent over thirty years in prayer, fasting, and Scripture study in pursuit of God's wisdom. He describes a series of extended prayer campaigns over decades — for wisdom, freedom from fear, generosity, and the glory of God — each answered in surprising ways that produced the books and articles on this site. His MIT education sharpened the analytical mind that he brings to the Bible's mathematical and structural patterns, while his classes at Gordon-Conwell deepened his theological foundations. The page is less a biography than a testimony that the wisdom on this site was given by God to a man who asked persistently and was answered abundantly.",
    "blueprint.md": "This article presents the architectural metaphor of Lady Wisdom's House from Proverbs as a literal map of how the Bible's wisdom is organized and interconnected, with foundation, seven pillars, and roof each corresponding to biblical structures. The foundation is the Law (the five books of Moses), symbolized by lapis lazuli; the seven pillars are Psalms, Job, Proverbs, Song of Songs, Ecclesiastes, Matthew, and Revelation, unified by the Growth Pattern of twenty-eight times and the sevenfold Harvest Pattern. The pillars are arranged in Harvest Pattern order — from Psalms (Preparation) through Job (Plowing), Proverbs (Planting), Song of Songs (Watering), Ecclesiastes (Plucking), Matthew (Producing), to Revelation (Peace). Jesus' saying that something greater than Solomon is here is explained by showing how his Harvest Pattern governs the arrangement of all seven pillars, making Christ's wisdom surpass Solomon's.",
    "books.md": "This page presents all of Paul Chernoch's published books with descriptions and Amazon purchase links, spanning fiction and nonfiction. Fiction includes A Most Refined Dragon (2015), a fantasy romance about a doctor who soul-swaps with a dragon on an alien world. Nonfiction works include The Endless Hunt (2012), a personal search for the twelve heavenly treasures Jesus described; Job Rises (2019), which draws thirteen keys to resilience from the Book of Job; and the two-volume prophetic study Peace, like Solomon Never Knew and Plague, Precept, Prophet, Peace, which together develop the author's system of prophetic clocks and biblical numerology. All books are available as e-books on Amazon, with most also in paperback.",
    "building-a-house.md": "Ecclesiastes 10 is decoded as an extended metaphor about building a house, with each parable in the chapter — from digging a pit to hammering a roof — corresponding to a stage of construction and prophesying an era of world history from 880 to 2080 AD. The author's theory of Fractal Historicism is applied to show how the same twenty-eight-times pattern governs both an individual human life and the whole of human history simultaneously. The productive years of the Grand Father Clock (880-2080 AD), divided into twelve 100-year eras, correspond to Ecclesiastes chapter 10 and its parables about wise and foolish work. Each building parable is shown to prophesy a specific era of civilization, from the fall of Charlemagne's empire to the rise of modern democratic and technological society.",
    "celestial-clocks.md": "This article surveys nineteen celestial prophetic clocks — structures where each prophetic era covers the same span of years, governed by the motions of the heavenly bodies. Each clock is named, its Scripture source identified, its timespan and period given, and its most significant prophecies noted. Major clocks include the Creation Clock (seven 1,000-year days), the Temple Dedication Clocks (twenty-two 120-year intervals from Solomon), Solomon's Celestial Clock (twenty-eight 120-year periods from 960 BC), and the Master Psalm Clock (fifty 42-year periods). Together these clocks form a comprehensive prophetic system covering all of history from creation to Christ's return, with a newly discovered Order of Salvation Clock based on the Beatitudes and Psalm 19 added to the catalog.",
    "chronology-of-judges.md": "This article tackles the thorny chronological puzzle of the era of the Judges by proposing a consistent set of seven rules that reconcile all major constraints without distorting the biblical text. Key innovations include treating Joshua as a teenager during the Exodus so his rule spans a full Jubilee cycle, treating periods of oppression as carved out of the preceding judgeship rather than added separately, and limiting Saul's reign to twelve years based on the timeline of the Ark of the Covenant. The resulting chronology fits within the 480 years from the Exodus to Solomon's temple given in 1 Kings 6:1 while honoring the 300-year figure from Jordan to Jephthah in Judges 11. The article is a distillation of two chapters from Plague, Precept, Prophet, Peace that established this framework.",
    "chronology.md": "This overview article on biblical chronology explains why God designed the Bible's timeline to be estimable but not exact — reserving precise knowledge for the diligent — and describes the author's goal of establishing dates accurate to within a decade. The key insight is that genealogical records round down each father's age at a son's birth, causing a cumulative undercount of about ten years across twenty pre-Abrahamic generations, placing the creation at approximately 4020 BC rather than Ussher's 4004 BC. Two uses of time in biblical prophecy are distinguished: exact countdowns that demand precision (like Daniel's seventy weeks) and prophetic clocks that tolerate small errors in start dates (like Solomon's twenty-eight times). Articles linked from this page cover the creation date, the sojourn in Egypt, the judges, and Solomon's lifespan.",
    "commandment-clocks.md": "This article describes five prophetic clocks structured according to the Ten Commandments, where each era corresponds to one commandment and contains a historical event that violates or honors that law. The most striking example is Moses' Commandment Clock for the Church, which maps the Black Plague of the 14th century — with its signature boils — to the sixth Exodus plague and the sixth commandment against murder, as God's judgment for the church's violence in the Crusades and Inquisition. A parallel clock for Israel spans from the Exodus to the death of Christ, with 148-year periods matching three to four Israelite generations. Job's Empire Clock extends the pattern across all of human history, matching each of ten major world empires to the commandment they most grievously violated.",
    "consecration.md": "This article surveys biblical models for ordination — from Melchizedek to the Aaronic priesthood to the apostles — before focusing on an often-overlooked model: the ordination of Job. After Job's friends offer a burnt offering at God's command, God empowers Job to forgive their sins, making Job the first person in the Bible explicitly authorized to grant forgiveness to others — a priestly act. This event is shown to parallel the Levitical ordination ceremony step by step: sacrifice, ceremony, divine appointment, and delegation of authority. The article argues that this Joban model of ordination, combined with a prophetic metaphor involving childbirth, provides the biblical foundation for understanding how women came to be ordained.",
    "contact.md": "A brief, warmly written contact page that provides the author's email address in a playful, spam-resistant format, asking readers to begin their subject line with 'Wisdom:' to avoid being swallowed by the bottomless pit of junk mail. The tone is humorous but genuine, reflecting the author's desire to hear from readers who have been challenged or blessed by the articles on the site.",
    "daily-scriptoquote.md": "The Daily Scryptoquote is an interactive cryptogram puzzle where a Scripture verse is encoded each day using a letter-substitution cipher, and visitors type in their letter guesses to decode it. Correct guesses propagate throughout the puzzle, and players can start over or reveal the answer using on-screen buttons. The feature is powered by the open-source Gryptocram JavaScript library and presents a different Bible verse every day with a randomly chosen cipher. The author shares his childhood love of newspaper cryptoquotes, which he often solved in under three minutes, and invites readers to test their own speed.",
    "dating-the-creation.md": "This article works through the biblical genealogies and chronological guardrails — the 400-year Egyptian affliction, the 430-year sojourn, the 300 years from Jordan to Jephthah, and the 480 years from the Exodus to Solomon's temple — to establish a creation date of approximately 4020 BC. A detailed table traces Anno Mundi years from Adam through the patriarchs to Solomon's temple, with corrections for the rounding errors introduced when genealogical ages are recorded as whole numbers. The key innovation is applying non-accession-year rounding corrections to the pre-Abrahamic genealogies, adding roughly ten years to Ussher's 4004 BC estimate. The result is a chronology calibrated for prophetic clock use rather than absolute precision.",
    "defining-153.md": "This article establishes the precise duration of Noah's Flood as 153 days by analyzing the calendrical mathematics of the flood's start (17th of the 2nd month) and end (17th of the 7th month). Since a 152-day span cannot arise from any pair of consecutive calendar months, and seven of the eleven possible start months yield exactly 153 days — including theologically favored months like Nisan and Tishri — the 153-day conclusion has both mathematical probability (63%) and theological support. As the seventeenth triangular number (1+2+...+17=153), this connects the flood's duration to the number 17, which means victory — God's total victory over human wickedness. This discovery is the key to unlocking the meaning of the 153 fish in John 21 and the five months of the Revelation 9 locusts.",
    "discipleship-model.md": "The author introduces a forthcoming series of three books on Christian discipleship, dividing the subject into speaking with God, salvation, and sanctification within the framework of the twelve-step Ordo Salutis of the Reformed tradition. The first book, The Redeemed Shall Talk, addresses Illumination — the spiritual awakening that makes hearing God clearly possible and that must precede all discipleship. The second book, The Redeemed Shall Walk, covers the full plan of Salvation — all twelve steps from election to glorification. A third book, The Redeemed Shall Grow, will map the milestones of Christian growth after initial salvation, drawing on Solomon's Growth Pattern and Jesus' Harvest Pattern.",
    "discipleship.md": "This article describes seven spirit-led facets of discipleship, each corresponding to one of the seven spirits of God named in Isaiah 11, discovered by the author during a period of illness and refined through months of study in Paul's letters. The seven facets — Center, Cost, Content, Clarity, Course, Communion, and Courage — constitute not a checklist but a living process in which the Holy Spirit changes the disciple's value system, making the treasures of heaven more desirable than anything the world offers. The author's personal testimony of memorizing the Sermon on the Mount, searching for heavenly treasures, and being guided through prayer and suffering illustrates each facet. Paul's seven letters from Romans to Colossians are shown to map the same course of discipleship in sequence.",
    "dreams.md": "This article classifies twenty-one types of dreams found in Scripture — from divine promises, commands, and warnings to nightmares from the enemy, day-residue visions, and prophetic lies — and offers practical guidance on how to interpret them safely. The author's own experience includes a healing dream from God in 1985 that permanently cured his fear of death, as well as costly episodes of heeding false dreams that led him astray. The central warning is that one should never act solely on the basis of a dream; every dream must be weighed against Scripture, other sources of wisdom, and whether it bears good fruit. The article emphasizes that only Daniel was granted understanding of all visions and dreams, making humility and caution the essential posture for everyone else.",
    "emotional-prophecies-of-the-psalms.md": "This article presents the stunning claim that the Psalms contain not just historical and Messianic prophecies but emotional prophecies — God's foreknowledge of how his people would feel in every era of history, expressed thousands of years in advance. The author discovered during his study of the Psalter that each major section (Psalms 1-110, the Acrostic Clock, the Final Ascent, and Psalms 1-28 in the Growth Pattern) prophesies not only events but emotional states — a form of prophetic empathy unlike anything previously identified. This means the Psalms are not merely comfort for generic human suffering but targeted emotional care for people in particular eras, showing that God knows exactly how a twenty-first century believer will feel and has prepared a response. The discovery transformed the author's understanding of the Psalms from analytical to deeply personal, revealing the astonishing compassion of God for the most frail aspects of our humanity.",
    "empire-clocks.md": "This article describes four Empire Clocks — prophetic structures that follow a sequence of world empires rather than equal time periods — covering Daniel's dream of the statue, the seven kingdoms of Revelation, Job's Empire Clock, and Habakkuk's Clock. Empires are symbolized throughout Scripture as beasts, metals, trees, or military insignia, each symbolic category capturing a different dimension: behavior (beasts), splendor (metals), and fruit (vegetation). A main sequence of ten empires from Babel to Leviathan appears across the prophets, most of which captured Jerusalem and were judged by God in the order of the Ten Commandments. Job's Empire Clock, the most comprehensive, traces all ten of those empires in order, demonstrating that God has been systematically judging humanity's great powers for thousands of years.",
    "foundation.md": "This article establishes the Ten Commandments as the foundation of Lady Wisdom's House — the Law symbolized by lapis lazuli on which God's own throne rests and upon which Isaiah promised to rebuild Jerusalem. The commandments are shown to be embedded in the structures of Hannah's prayer, Paul's letters to Timothy, the Gospel of Matthew, Psalm 119, and Job's prophetic history of empires, making them the matrix for all of God's wisdom. The article takes a dual approach: displaying God's wrath channeled through the commandments in measured, deliberate historical judgments, and showing each commandment as a protective wall around a specific heavenly treasure that God wants his people to value. Together these perspectives transform the Law from a fearful threat into a glorious expression of divine love.",
    "four-horsemen.md": "This article is a work in progress — a future exploration of the Four Horsemen of the Apocalypse from Revelation 6, examining their identities and the eras of history they represent. Check back for the completed article.",
    "generational-clocks.md": "This article introduces five Generational Clocks — prophetic structures that measure time by human generations rather than years — and summarizes their history of discovery and the key insight that God counts people, not just celestial mechanics. The five clocks (Job's Anti-jubilee Clock, Job's Chapter Clock, the Shepherd's Clock of Psalm 119, the Cosmic Chiasm, and the Acrostic Clock of Psalms 111-112) each cover history from the creation or Abraham to Christ's return, with period lengths of 50, 119, or 120 years. Detailed tables of generation numbers, start and end years, Bible verse references, and prophetic interpretations are promised for each clock. The article narrates the intellectual journey of discovery that led from Matthew's genealogy to Job's clocks to the Psalms, revealing an unexpectedly rich prophetic system.",
    "generations-come-and-go.md": "Inspired by Ecclesiastes 1:4, this article narrates the author's discovery that human history has a forty-two generation structure mirroring God's dealings with mankind, drawn initially from Matthew's genealogy of Jesus. The article introduces autocorrelation — a signal-processing technique — as a mathematical analogy for detecting the characteristic frequency behind God's prophetic calendar. It establishes a Cosmic Chiasm — a mirror-symmetry between the earliest and latest eras of history — as the framework for understanding how God's plan unfolds from creation to Christ's return. The key insight is that God measures time by generations because people are more important to him than the mechanical motion of the stars.",
}

for source, synopsis in synopses.items():
    old = f"  source: {source}\n  synopsis: No synopsis yet"
    new = f"  source: {source}\n  synopsis: {synopsis}"
    if old in content:
        content = content.replace(old, new, 1)
    else:
        print(f"WARNING: Could not find entry for {source}")

with open(filepath, "w") as f:
    f.write(content)

remaining = content.count("No synopsis yet")
print(f"Done. Remaining 'No synopsis yet': {remaining}")
